/*
 * Per-module bundle attribution.
 *
 * Decodes a Vite/Rollup sourcemap and attributes generated bytes back to the
 * source file that produced them, then aggregates by package. This is the
 * measurement that answers "what is actually in this chunk" rather than
 * inferring it from string markers, which minification can hide.
 *
 * Approximation, stated plainly: a segment's generated range is measured from
 * its start column to the next segment's start column on the same line. That
 * over-attributes slightly where a segment is short and the gap is padding, and
 * it counts characters rather than bytes — for a UTF-8 bundle with little
 * non-ASCII the two are very close, and the ranking is unaffected.
 */

const fs = require('node:fs');
const path = require('node:path');

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const CHAR_TO_INT = new Map([...BASE64].map((char, index) => [char, index]));

/** Decode one VLQ-encoded line of segments into absolute values. */
const decodeLine = (line, previous) => {
  const segments = [];
  let cursor = 0;
  let sourceIndex = previous.sourceIndex;
  let sourceLine = previous.sourceLine;
  let sourceColumn = previous.sourceColumn;

  while (cursor < line.length) {
    const values = [];

    while (cursor < line.length && line[cursor] !== ',') {
      let result = 0;
      let shift = 0;
      let digit;

      do {
        digit = CHAR_TO_INT.get(line[cursor]);
        cursor += 1;
        result += (digit & 31) << shift;
        shift += 5;
      } while (digit & 32);

      const negative = result & 1;
      result >>= 1;

      values.push(negative ? -result : result);
    }

    // Skip the separator.
    if (line[cursor] === ',') cursor += 1;

    if (values.length >= 4) {
      sourceIndex += values[1];
      sourceLine += values[2];
      sourceColumn += values[3];

      segments.push({ column: values[0], sourceIndex, sourceLine, sourceColumn });
    }
  }

  return {
    segments,
    previous: { sourceIndex, sourceLine, sourceColumn },
  };
};

/** Aggregate generated characters per source file. */
const analyse = (mapPath) => {
  const map = JSON.parse(fs.readFileSync(mapPath, 'utf8'));
  const generatedPath = mapPath.replace(/\.map$/, '');
  const generatedLines = fs.readFileSync(generatedPath, 'utf8').split('\n');

  const totals = new Map();
  let state = { sourceIndex: 0, sourceLine: 0, sourceColumn: 0 };

  map.mappings.split(';').forEach((line, lineIndex) => {
    const { segments, previous } = decodeLine(line, state);
    state = previous;

    if (segments.length === 0) return;

    const lineLength = (generatedLines[lineIndex] ?? '').length;

    segments.forEach((segment, index) => {
      const next = segments[index + 1];
      const end = next ? next.column : lineLength;
      const size = Math.max(0, end - segment.column);

      const source = map.sources[segment.sourceIndex] ?? '(unknown)';

      totals.set(source, (totals.get(source) ?? 0) + size);
    });
  });

  return totals;
};

/** Reduce a source path to the package or app area it belongs to. */
const groupOf = (source) => {
  const normalized = source.replace(/\\/g, '/');

  const nodeModules = normalized.lastIndexOf('node_modules/');

  if (nodeModules !== -1) {
    const rest = normalized.slice(nodeModules + 'node_modules/'.length);
    const parts = rest.split('/');

    return parts[0].startsWith('@') ? `${parts[0]}/${parts[1]}` : parts[0];
  }

  const src = normalized.lastIndexOf('/src/');

  if (src !== -1) {
    const rest = normalized.slice(src + 5);
    const parts = rest.split('/');

    return `app:${parts.slice(0, 2).join('/')}`;
  }

  return normalized.split('/').slice(-2).join('/');
};

const [target] = process.argv.slice(2);

if (!target) {
  console.error('usage: node analyse-chunk.cjs <path/to/chunk.js.map>');
  process.exit(1);
}

const totals = analyse(path.resolve(target));
const grouped = new Map();

for (const [source, size] of totals) {
  const group = groupOf(source);
  grouped.set(group, (grouped.get(group) ?? 0) + size);
}

const totalBytes = [...totals.values()].reduce((sum, size) => sum + size, 0);

console.log(`\n${path.basename(target)}  (attributed ${(totalBytes / 1024).toFixed(1)} KB)\n`);

for (const [group, size] of [...grouped].sort((a, b) => b[1] - a[1]).slice(0, 18)) {
  const share = ((size / totalBytes) * 100).toFixed(1);
  const bar = '#'.repeat(Math.max(1, Math.round(share / 2)));

  console.log(`  ${(size / 1024).toFixed(1).padStart(8)} KB  ${share.padStart(5)}%  ${group}  ${bar}`);
}

console.log('\n  top individual files:');

for (const [source, size] of [...totals].sort((a, b) => b[1] - a[1]).slice(0, 12)) {
  const short = source.replace(/\\/g, '/').split('/').slice(-3).join('/');

  console.log(`    ${(size / 1024).toFixed(1).padStart(7)} KB  ${short}`);
}
